insert into public.ip_questions select * from jsonb_populate_recordset(null::public.ip_questions, '[{"id": "q-bddc49ec8f9defc8b0bb9b7f", "prompt": "본인의 강점을 살려 우리 조직에 들어와 발휘 하는 있는 점?", "category": "personality", "topic_ids": ["self", "motivation"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-b25108c2f46dcb79eb37208b", "prompt": "공동 목표를 위해 자신이 희생한 경험은?", "category": "personality", "topic_ids": ["teamwork", "responsibility"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-82a153eaf2b3f4321beda74d", "prompt": "자신의 단점?", "category": "personality", "topic_ids": ["self", "failure"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-55ffd64673ca158298bf4b60", "prompt": "공무원들의 고쳐야 할 점 / 공직관 심화", "category": "personality", "topic_ids": ["public", "integrity", "achievement"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-1a757da6894404dd4e00aaaa", "prompt": "학창시절 동아리 활동은?", "category": "personality", "topic_ids": ["teamwork", "responsibility", "self"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-a529c11e48d752793991a7e7", "prompt": "사람들 간의 문제를 해결한 적은?", "category": "personality", "topic_ids": ["communication", "stress"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-6fd5dd758562b9834ca053a2", "prompt": "(불안형 질문)일이 육체적으로 힘들고 박봉인데 선택한 이유는?", "category": "personality", "topic_ids": ["motivation", "responsibility"], "tracks": [], "status": "draft", "revision": 1, "created_at": "2026-10-20T00:00:00Z", "updated_at": "2026-10-20T00:00:00Z"}, {"id": "q-860ca464b